mapper.select:
SELECT d.id AS destination_id, d.region_id AS region_id, dt.name, di.image_url, cc.region_name AS region_name, d.season, c.id AS category_id, c.name AS category_name FROM destinations d LEFT JOIN destination_translations dt ON d.id = dt.destination_id AND dt.language_code = 'ko' LEFT JOIN destination_images di ON d.id = di.destination_id AND di.is_main = 1 LEFT JOIN country_categories cc ON d.region_id = cc.id LEFT JOIN destination_categories dc ON d.id = dc.destination_id LEFT JOIN categories c ON dc.category_id = c.id WHERE d.season = #{season}
AND c.id = #{categoryId}
ORDER BY RAND() LIMIT #{limit}
